<?php

declare(strict_types=1);

namespace App\Entities\Concerns;

use Doctrine\ORM\Mapping as ORM;
use Illuminate\Support\Str;

/**
 * UUID primary key, generated by the application (not the database), so an
 * entity has its id before it is persisted. Also the single place to switch
 * to time-ordered UUIDs (v7) later.
 */
trait HasUuid
{
    #[ORM\Id]
    #[ORM\Column(type: 'guid')]
    private string $id;

    public function id(): string
    {
        return $this->id;
    }

    /** A given id must be a UUID; it is stored lower-case so lookups are exact. */
    private function assignId(?string $id): void
    {
        if ($id !== null && ! Str::isUuid($id)) {
            throw new \InvalidArgumentException(sprintf('Id "%s" is not a valid UUID.', $id));
        }

        $this->id = $id === null ? (string) Str::uuid() : strtolower($id);
    }
}
